{% set data = get_order_sheet_stage_workflow(doc.name) %}
{% set items = data.rows %}
<style>
  body { font-family: Arial, sans-serif; font-size: 12px; color: #111; padding: 10px; }
  .print-format { margin-top: 0mm; margin-right: 0mm; margin-bottom: 0mm; margin-left: 0mm; orientation: Landscape; }

  /* Header/table density tuned to fit more rows per page — a 33-item Order
     Sheet still spills to page 2 on wkhtmltopdf (which doesn't reliably repeat
     <thead> across page breaks, so a page-2-only reader saw an unlabeled
     grid); this is the "shrink to fit more" mitigation, not a full fix —
     see CLAUDE.md item 96/119/120 for why the page-2 header-repeat itself
     is still an open gap (this Frappe version has no Chrome PDF generator
     to fall back on — pdf_generator's only real option is wkhtmltopdf). */
  /* Negative side-margins matching body's own padding so the letterhead image
     bleeds truly edge-to-edge (100% of the page) instead of 100% of the
     10px-inset content area it would otherwise be constrained to. */
  .jos-header { text-align: center; margin: 0 0 6px; }
  /* Circular logo (1600x1600, logo.jpeg) — height-capped and centered, not
     width:100% (that was for the old wide banner letterhead and stretched
     this square mark into a huge blown-up circle). */
  .jos-header img { max-height: 60px; width: auto; display: block; margin: 0 auto 4px; }
  .jos-header h2 { margin: 0; font-size: 16px; letter-spacing: 1px; }

  .jos-ref { text-align: center; margin-bottom: 6px; }
  .jos-date-box { display: inline-block; border: 1.5px solid #d97757; padding: 2px 10px; font-weight: bold; font-size: 11px; color: #111; margin-right: 10px; }
  .jos-items-count { font-size: 11px; color: #555; }

  table.jos-items { width: 100%; border-collapse: collapse; margin-bottom: 10px; }
  table.jos-items th { background: #fff; color: #111; font-weight: bold; border-bottom: 2px solid #d97757; padding: 3px 6px; text-align: left; font-size: 10px; white-space: nowrap; }
  table.jos-items td { border-bottom: 1px solid #ddd; padding: 2px 6px; vertical-align: middle; font-size: 10px; }
  table.jos-items tr:nth-child(even) td { background: #fafafa; }
  table.jos-items td.jos-item-code { font-weight: bold; }
  table.jos-items th.jos-stage-col,
  table.jos-items td.jos-stage-cell { text-align: center; white-space: nowrap; }

  .jos-subnote { font-size: 9px; margin-top: 1px; }
  /* Adjusted qty (pcs_to_make/logs_to_make) — this replaces the ordered qty
     as THE number the floor works to, so it's the only number shown, sized
     up so it reads at a glance. No "adjusted"/"confirmed" language — that
     distinction is a back-office concern, not the operator's. */
  .jos-qty-final { font-size: 12px; font-weight: 700; color: #111; }

  .jos-stage-na { color: #aaa; }
  .jos-stage-pending { color: #999; }
  .jos-stage-done { color: #111; }
  .jos-stage-current { font-weight: bold; background: #fdf1ec; }
  .jos-stage-hold { font-weight: bold; color: #b3261e; }

  .jos-empty { text-align: center; padding: 20px; color: #888; font-size: 12px; }

  .jos-footer { margin-top: 20px; width: 100%; }
  .jos-footer td { padding: 4px; }
  .sig-line { border-top: 1px solid #444; padding-top: 4px; text-align: center; font-size: 10px; color: #555; }
</style>

<div class="jos-header">
  <img src="/files/logo.jpeg">
  <h2>JOB ORDER SUMMARY</h2>
</div>

<div class="jos-ref">
  {% if doc.sales_order %}
  <span class="jos-date-box">SO: {{ doc.sales_order }}</span>
  {% endif %}
  <span class="jos-date-box">Sheet Date: {{ frappe.utils.formatdate(doc.creation, "dd-MMM-yy") if doc.creation else "" }}</span>
  <span class="jos-items-count">Items: {{ items | length }}</span>
</div>

{% if items %}
<table class="jos-items">
  <thead>
    <tr>
      <th>#</th>
      <th>Item Code</th>
      <th>Item Name</th>
      <th>Qty</th>
      {% if data.any_color %}<th>Color</th>{% endif %}
      {% if data.any_width_mm %}<th>Width (MM)</th>{% endif %}
      {% if data.any_length_mtr %}<th>Length (MTR)</th>{% endif %}
      {% if data.any_qty_pkg %}<th>Qty/Pkg</th>{% endif %}
      {% if data.any_total_pkg %}<th>Total Pkg</th>{% endif %}
      <th>Brand</th>
      <th>Core</th>
      <th>CTN</th>
      <th>Shrink Film</th>
      <th>No. of Logs</th>
      <th>Packing Type</th>
      <th>Size</th>
      <th class="jos-stage-col">Coating</th>
      <th class="jos-stage-col">Slitting</th>
      <th class="jos-stage-col">Rewinding</th>
      <th class="jos-stage-col">Cutting</th>
      <th class="jos-stage-col">Packing</th>
      <th class="jos-stage-col">RTD</th>
    </tr>
  </thead>
  <tbody>
  {% for item in items %}
    <tr>
      <td>{{ loop.index }}</td>
      <td class="jos-item-code">{{ item.item_code }}</td>
      <td>{{ item.item_name or "" }}</td>
      <td>
        {%- if item.uom == "PCS" and item.pcs_to_make -%}
        <div class="jos-qty-final">{{ item.pcs_to_make }} PCS</div>
        {%- elif item.uom == "SQMT" and item.logs_to_make -%}
        <div class="jos-qty-final">{{ item.logs_to_make }} SQMT</div>
        {%- else -%}
        <div>{{ item.qty or 0 }} {{ item.uom or "" }}</div>
        {%- endif -%}
      </td>
      {% if data.any_color %}<td>{{ item.color or "-" }}</td>{% endif %}
      {% if data.any_width_mm %}<td>{{ item.width_mm if item.width_mm else "-" }}</td>{% endif %}
      {% if data.any_length_mtr %}<td>{{ item.length_mtr if item.length_mtr else "-" }}</td>{% endif %}
      {% if data.any_qty_pkg %}<td>{{ (item.qty_pkg | int) if item.qty_pkg else "-" }}</td>{% endif %}
      {% if data.any_total_pkg %}<td>{{ (item.total_pkg | int) if item.total_pkg else "-" }}</td>{% endif %}
      <td>{{ item.brand or "-" }}</td>
      <td>{{ item.core or "-" }}</td>
      <td>{{ item.ctn or "-" }}</td>
      <td>{{ item.shrink_film or "-" }}</td>
      <td>{{ item.no_of_logs if item.no_of_logs else "-" }}</td>
      <td>{{ item.packing_type or "-" }}</td>
      <td>{{ item.size or "-" }}</td>
      {% for st in item.stages %}
        {%- if not st.in_route -%}
        <td class="jos-stage-cell jos-stage-na">&mdash;</td>
        {%- elif st.status == "Completed" -%}
        <td class="jos-stage-cell jos-stage-done">
          <div>{{ st.machine or "Done" }}</div>
          {%- if st.operator -%}<div class="jos-subnote">{{ st.operator }}</div>{%- endif -%}
        </td>
        {%- elif st.status == "On Hold" -%}
        <td class="jos-stage-cell jos-stage-hold">{{ st.machine or "" }} (Hold)</td>
        {%- elif st.is_current -%}
        <td class="jos-stage-cell jos-stage-current">{{ st.machine or "Pending" }}</td>
        {%- else -%}
        <td class="jos-stage-cell jos-stage-pending">pending</td>
        {%- endif -%}
      {% endfor %}
    </tr>
  {% endfor %}
  </tbody>
</table>
{% else %}
<div class="jos-empty">No items to print for this order.</div>
{% endif %}

<table class="jos-footer">
  <tr>
    <td style="width:33%"><div class="sig-line">Operator Signature</div></td>
    <td style="width:33%"><div class="sig-line">Actual Output Qty / Date</div></td>
    <td style="width:33%"><div class="sig-line">Checked By</div></td>
  </tr>
</table>
